"""Generate only the five reviewed read-only camera observation additions."""
from pathlib import Path
import argparse,hashlib,json
R=Path(__file__).resolve().parents[1];sha=lambda b:hashlib.sha256(b).hexdigest()
PARENTS={'th14-compare-native-campaign-retained-camera-nov01.mjs': 'abaf89329cf21a3abdc6f1e421320b56c0ed60a0a67ed295e43b0054a26e31c1', 'th14-compare-native-extra-campaign-nov01.mjs': 'c07b3cf80927af8114a11a69e557eef9f9710f9b183b82601c7a3b0b85f221d9'}
PATCHES=[("const combatSnapshots=[],combatDifferences=[],nativeCombatIndex=JSON.parse(read(resolve(nativeHome,'combat-pool-index.json'))),nativeCombatByCallback=new Map(nativeCombatIndex.snapshots.map(x=>[x.callback,x]));\n", "const combatSnapshots=[],combatDifferences=[],nativeCombatIndex=JSON.parse(read(resolve(nativeHome,'combat-pool-index.json'))),nativeCombatByCallback=new Map(nativeCombatIndex.snapshots.map(x=>[x.callback,x]));\nconst fullCameraRows=[],fullCameraCounts={},fullCameraFirst=[];const fullCameraIndices=Array.from({length:73},(_,i)=>i).filter(i=>i!==22&&i!==23);\n"), ('function compare(index){\n', 'function compare(index){\n if(index>0){\n  assert.equal(c.full_camera_observed_callback(),index+1);\n  for(const word of fullCameraIndices){\n   const actual=c.full_camera_word(word)>>>0,expected=cameraRaw.readUInt32LE(index*292+word*4);fullCameraRows.push(actual);\n   if(actual!==expected){fullCameraCounts[word]=(fullCameraCounts[word]??0)+1;if(fullCameraFirst.length<16)fullCameraFirst.push({callback:index+1,nativeWord:word,actual,expected});}\n  }\n }\n\n'), ('initialCreationCount=c.observed_creation_count();compare(0);assert.equal(c.public_replay_clock(1/60),1);let end=null;\n', 'initialCreationCount=c.observed_creation_count();compare(0);assert.equal(c.public_replay_clock(1/60),1);assert.equal(c.full_camera_install(),1);\nlet end=null;\n'), ("report.sceneCopyWordHandoffs=sceneCopyWordHandoffs;report.sceneCopyObservationSha256=options.has('scene-copy-observation')?sha(read(resolve(root,options.get('scene-copy-observation')))):null;\n", "report.sceneCopyWordHandoffs=sceneCopyWordHandoffs;report.sceneCopyObservationSha256=options.has('scene-copy-observation')?sha(read(resolve(root,options.get('scene-copy-observation')))):null;\nconst fullBytes=Buffer.from(new Uint32Array(fullCameraRows).buffer);\nwrite(resolve(out,'full-camera.u32'),fullBytes,{flag:'wx'});\nwrite(resolve(out,'full-camera-report.json'),JSON.stringify({readOnlyExpandedCameraObservation:true,firstCallback:2,callbacksCompared:rows.length/32-1,nativeWordIndices:fullCameraIndices,comparedFieldsPerCallback:71,opaqueNativeWordIndicesNotAccepted:[22,23],nativeTrailingWordsNotCaptured:[73,74],counts:fullCameraCounts,first:fullCameraFirst,allExpandedCapturedWordsEqual:Object.keys(fullCameraCounts).length===0,portableSha256:sha(fullBytes),hostClockOverridesAdded:false,originalStateValuesProvidedToEngine:false,completeGame:false},null,2)+'\\n',{flag:'wx'});\nreport.readOnlyExpandedCameraObservation=true;\n"), ("assert(allocationReports.every(row=>row.allHandlesFileScriptEqual),'Observed publication window differs');\n", "assert(allocationReports.every(row=>row.allHandlesFileScriptEqual),'Observed publication window differs');\n\nassert.equal(Object.keys(fullCameraCounts).length,0,'Expanded captured camera fields differ');\n")]
def driver_source(extra=False):
 name=list(PARENTS)[int(extra)];raw=(R/'tools'/name).read_bytes();assert sha(raw)==PARENTS[name]
 text=raw.decode().replace('\r\n','\n')
 for old,new in PATCHES:
  assert text.count(old)==1; text=text.replace(old,new)
 return text.replace('\n','\r\n').encode()
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--write',action='store_true');p.add_argument('--check',action='store_true');a=p.parse_args();assert a.write!=a.check
 for extra,name in [(False,'th14-compare-native-full-camera-nov04.mjs'),(True,'th14-compare-native-extra-full-camera-nov04.mjs')]:
  path=R/'tools'/name;data=driver_source(extra)
  if a.write and not path.exists():path.write_bytes(data)
  assert path.read_bytes()==data;print(json.dumps(dict(path=name,sha256=sha(data),reviewedReadOnlyAdditions=5,hostClockOverridesAdded=False)))
if __name__=='__main__':main()
